<?php require __DIR__.'/bootstrap.php';$u=uid();$error='';$report='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{if(!class_exists('ZipArchive'))throw new RuntimeException('PHP ZIP extension is required.');if(!isset($_FILES['archive'])||$_FILES['archive']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Upload failed. Check PHP upload_max_filesize and post_max_size.');$max=max(1,min(1000,(int)setting('max_import_mb','100')))*1048576;if($_FILES['archive']['size']>$max)throw new RuntimeException('ZIP exceeds configured import limit.');$zip=new ZipArchive();if($zip->open($_FILES['archive']['tmp_name'])!==true)throw new RuntimeException('Cannot read ZIP.');$count=0;$skipped=0;$failed=0;$labels=[];$errors=[];$totalUncompressed=0;$maxEntries=30000;if($zip->numFiles>$maxEntries)throw new RuntimeException('Too many ZIP entries.');
for($i=0;$i<$zip->numFiles;$i++){$stat=$zip->statIndex($i);$totalUncompressed+=$stat['size'];if($totalUncompressed>1073741824)throw new RuntimeException('Uncompressed archive exceeds 1 GB safety limit.');}
for($i=0;$i<$zip->numFiles;$i++){$path=$zip->getNameIndex($i);if(!preg_match('~(?:^|/)Keep/[^/]+\.json$~i',$path))continue;$raw=$zip->getFromIndex($i);if(strlen($raw)>2097152){$failed++;continue;}$item=json_decode($raw,true);if(!is_array($item)){$failed++;continue;}$title=mb_substr((string)($item['title']??''),0,255);$body=(string)($item['textContent']??'');$kind='text';if(!empty($item['listContent'])&&is_array($item['listContent'])){$kind='checklist';$lines=[];foreach($item['listContent'] as $part){$lines[]=(!empty($part['isChecked'])?'[x] ':'[ ] ').(string)($part['text']??'');}$body=implode("\n",$lines).($body!==''?"\n".$body:'');}if(strlen($body)>2000000){$failed++;continue;}$hash=hash('sha256',$raw);if(q('SELECT id FROM mn_notes WHERE user_id=? AND source_hash=? LIMIT 1',[$u,$hash])->fetchColumn()){$skipped++;continue;}$category=null;$taglist=[];foreach(($item['labels']??[]) as $label){$name=trim((string)($label['name']??''));if($name==='')continue;$taglist[]=$name;if($category===null)$category=getcat($u,$name);} $created=!empty($item['createdTimestampUsec'])?(int)floor((int)$item['createdTimestampUsec']/1000000):time();$updated=!empty($item['userEditedTimestampUsec'])?(int)floor((int)$item['userEditedTimestampUsec']/1000000):$created;$created=max(1,min(time()+86400,$created));$updated=max(1,min(time()+86400,$updated));q('INSERT INTO mn_notes(user_id,category_id,title,body,kind,pinned,archived,source_hash,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$u,$category,$title,$body,$kind,!empty($item['isPinned'])?1:0,!empty($item['isArchived'])?1:0,$hash,date('Y-m-d H:i:s',$created),date('Y-m-d H:i:s',$updated)]);$nid=(int)db()->lastInsertId();set_tags($u,$nid,implode(',',$taglist));$count++;
// Google Keep attachments are referenced by relative filenames. Store privately, never in web root.
$prefix=substr($path,0,strrpos($path,'/')+1);foreach(($item['attachments']??[]) as $attachment){$filename=(string)($attachment['filePath']??'');if($filename===''||strpos($filename,'/')!==false||strpos($filename,'\\')!==false||strpos($filename,'..')!==false)continue;$entry=$prefix.$filename;$index=$zip->locateName($entry,ZipArchive::FL_NOCASE);if($index===false)continue;$info=$zip->statIndex($index);if($info['size']>10485760)continue;$data=$zip->getFromIndex($index);if($data===false)continue;$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($data);if(!in_array($mime,['image/jpeg','image/png','image/gif','image/webp','audio/mpeg','audio/mp4','audio/ogg','application/pdf'],true))continue;$storage=bin2hex(random_bytes(20));if(file_put_contents(__DIR__.'/storage/'.$storage,$data)===false)continue;q('INSERT INTO mn_attachments(note_id,user_id,stored_name,original_name,mime,size_bytes) VALUES(?,?,?,?,?,?)',[$nid,$u,$storage,$filename,$mime,strlen($data)]);}}
$zip->close();$report="Imported $count notes. Skipped $skipped already imported. $failed notes could not be read.";
}catch(Throwable $e){$error=$e->getMessage();error_log('MyNotes import error: '.$e->getMessage());}}
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MyNotes · Import</title><link rel="stylesheet" href="style.css"><header><a class="brand" href="index.php">My<span>Notes</span></a><a href="index.php">Back to notes</a></header><main><section class="panel"><h1>Import Google Keep</h1><p>Upload the original Google Takeout ZIP. Notes, labels, checklists, dates and supported attachments will be imported. The first label becomes the category; all labels remain as tags. Reimporting the same exported note is skipped.</p><p class="small">Keep the original ZIP as a backup. For large exports, the host may require increased PHP upload and execution limits. Import smaller ZIPs if needed.</p><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><?php if($report):?><p class="notice"><?=h($report)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Google Takeout ZIP</label><input type="file" name="archive" accept=".zip,application/zip" required><button>Import my notes</button></form></section></main></html>
